-- Migration 0033: learning-path structure moves to the database.
-- Source of truth for path validation is now path_maps (seeded from the
-- historical features/path/path-data.ts). The frontend keeps a built-in
-- copy as offline fallback; children read the static export
-- (npm run export:path), never the DB directly.
-- Seed is idempotent (ON CONFLICT DO NOTHING) so existing environments
-- that already edited maps in the admin keep their content.

CREATE TABLE public.path_maps (
  path_id text PRIMARY KEY,
  grade integer NOT NULL UNIQUE,
  title text NOT NULL,
  version integer NOT NULL DEFAULT 1,
  status text NOT NULL DEFAULT 'published',
  points jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT path_maps_status_ck CHECK (status IN ('draft', 'published')),
  CONSTRAINT path_maps_grade_ck CHECK (grade BETWEEN 1 AND 4),
  CONSTRAINT path_maps_id_ck CHECK (path_id ~ '^grade-[1-4]$')
);

ALTER TABLE public.path_maps ENABLE ROW LEVEL SECURITY;

